  1	package com.pousada.service;
  2	
  3	import com.pousada.domain.Reservation;
  4	import com.pousada.domain.ReservationStatus;
  5	import com.pousada.domain.Room;
  6	import com.pousada.domain.rateplans.CorporateRatePlan;
  7	import com.pousada.domain.rateplans.InvalidReservationException;
  8	import com.pousada.domain.rateplans.RatePlan;
  9	import com.pousada.domain.rateplans.RatePlanRegistry;
 10	import com.pousada.infra.MessageRepository;
 11	import com.pousada.infra.ReservationRepository;
 12	import com.pousada.infra.RoomRepository;
 13	import java.math.BigDecimal;
 14	import java.sql.SQLException;
 15	import java.text.DecimalFormat;
 16	import java.text.DecimalFormatSymbols;
 17	import java.time.LocalDate;
 18	
 19	public class ReservationService {
 20	    private final RoomRepository roomRepository;
 21	    private final ReservationRepository reservationRepository;
 22	    private final MessageRepository messageRepository;
 23	
 24	    public ReservationService(RoomRepository roomRepository, ReservationRepository reservationRepository,
 25	                             MessageRepository messageRepository) {
 26	        this.roomRepository = roomRepository;
 27	        this.reservationRepository = reservationRepository;
 28	        this.messageRepository = messageRepository;
 29	    }
 30	
 31	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 32	                                         LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan,
 33	                                         String companyCode) throws SQLException {
 34	        if (guests < 1) {
 35	            throw new ApiException("INVALID_REQUEST", "Reserva deve ter pelo menos 1 hóspede", 400);
 36	        }
 37	
 38	        if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
 39	            throw new ApiException("INVALID_REQUEST", "Data de saída deve ser após a entrada", 400);
 40	        }
 41	
 42	        Room room = roomRepository.findByNumber(roomNumber);
 43	        if (room == null) {
 44	            throw new ApiException("ROOM_NOT_FOUND", "Quarto não encontrado", 404);
 45	        }
 46	
 47	        if (guests > room.getCapacity()) {
 48	            throw new ApiException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto", 422);
 49	        }
 50	
 51	        if (!RatePlanRegistry.exists(ratePlan)) {
 52	            throw new ApiException("INVALID_REQUEST", "Plano de tarifa inválido", 400);
 53	        }
 54	
 55	        RatePlan plan = RatePlanRegistry.get(ratePlan);
 56	        try {
 57	            plan.validate(roomNumber, checkIn, checkOut, guests, companyCode);
 58	        } catch (InvalidReservationException e) {
 59	            throw new ApiException(e.getCode(), e.getMessage(), 400);
 60	        }
 61	
 62	        var conflictingReservations = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 63	        if (!conflictingReservations.isEmpty()) {
 64	            throw new ApiException("ROOM_UNAVAILABLE", "Quarto não disponível nas datas solicitadas", 409);
 65	        }
 66	
 67	        RatePlan.PriceCalculation priceCalc;
 68	        if (plan instanceof CorporateRatePlan corpPlan) {
 69	            priceCalc = corpPlan.calculatePrice(room, checkIn, checkOut, companyCode);
 70	        } else {
 71	            priceCalc = plan.calculatePrice(room, checkIn, checkOut);
 72	        }
 73	
 74	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 75	
 76	        Reservation reservation = new Reservation(
 77	            0,
 78	            roomNumber,
 79	            guestName,
 80	            guestEmail,
 81	            guestCpf,
 82	            checkIn,
 83	            checkOut,
 84	            guests,
 85	            ratePlan,
 86	            companyCode,
 87	            nights,
 88	            priceCalc.subtotal(),
 89	            priceCalc.discount(),
 90	            priceCalc.total(),
 91	            ReservationStatus.PENDING,
 92	            BigDecimal.ZERO,
 93	            null
 94	        );
 95	
 96	        return reservationRepository.save(reservation);
 97	    }
 98	
 99	    public Reservation getReservation(long id) throws SQLException {
100	        Reservation reservation = reservationRepository.findById(id);
101	        if (reservation == null) {
102	            throw new ApiException("RESERVATION_NOT_FOUND", "Reserva não encontrada", 404);
103	        }
104	        return reservation;
105	    }
106	
107	    public Reservation confirmReservation(long id, BigDecimal amountPaid) throws SQLException {
108	        Reservation reservation = getReservation(id);
109	        if (reservation.getStatus() != ReservationStatus.PENDING) {
110	            throw new ApiException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas", 409);
111	        }
112	
