  8	
  9	public abstract class BaseRatePlan implements RatePlan {
 10	
 11	    protected BigDecimal calculateNightlyPrice(Room room, LocalDate date) {
 12	        BigDecimal basePrice = room.getNightlyRate();
 13	        double seasonMultiplier = Season.getSeasonMultiplier(date);
 14	        return Money.multiply(basePrice, seasonMultiplier);
 15	    }
 16	
 17	    protected BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
 18	        BigDecimal total = BigDecimal.ZERO;
 19	        LocalDate current = checkIn;
 20	        while (current.isBefore(checkOut)) {
 21	            total = total.add(calculateNightlyPrice(room, current));
 22	            current = current.plusDays(1);
 23	        }
 24	        return Money.round(total);
 25	    }
 26	
 27	    protected int calculateNights(LocalDate checkIn, LocalDate checkOut) {
 28	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 29	    }
 30	
 31	    protected void validateBasic(int guests) {
 32	        if (guests < 1) {
 33	            throw new InvalidReservationException("INVALID_REQUEST", "Reserva deve ter pelo menos 1 hóspede");
 34	        }
 35	    }
 36	}
