252	    private static final Map<Room.RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
253	        Room.RoomType.STANDARD, new BigDecimal("520.00"),
254	        Room.RoomType.DELUXE, new BigDecimal("820.00"),
255	        Room.RoomType.SUITE, new BigDecimal("1200.00")
256	    );
