264	    public void validate(int roomNumber, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
265	        validateBasic(guests);
266	
267	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
268	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve começar numa sexta");
269	        }
270	
271	        LocalDate expectedCheckOut = checkIn.plusDays(2);
272	        if (!checkOut.equals(expectedCheckOut)) {
273	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve ter exatamente 2 noites");
274	        }
275	
276	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
277	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve terminar num domingo");
278	        }
279	    }
